(function(){'use strict';var plans={'3':{people:3,seat:79,base:199,meta:160,ai:100,setup:700},'5':{people:5,seat:79,base:199,meta:240,ai:180,setup:1000},'10':{people:10,seat:79,base:199,meta:400,ai:350,setup:1800}};var money=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});function boot(){document.querySelectorAll('.bmd-multi-sim').forEach(function(root){function el(k){return root.querySelector('[data-val="'+k+'"]')}function get(k){var e=el(k),n=e?Number(e.value):0;return Number.isFinite(n)?Math.max(0,n):0}function out(k,v){var e=root.querySelector('[data-out="'+k+'"]');if(e)e.textContent=money.format(v)}function calc(){var count=Math.max(1,Math.floor(get('people'))),month=count*get('seat')+get('base')+get('meta')+get('ai'),year=12*month+get('setup');out('month',month);out('year',year);out('per',month/count);out('equiv',year/12);}root.querySelectorAll('[data-team]').forEach(function(b){b.addEventListener('click',function(){var p=plans[b.getAttribute('data-team')];if(!p)return;Object.keys(p).forEach(function(k){if(el(k))el(k).value=p[k]});root.querySelectorAll('[data-team]').forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')});calc()})});root.querySelectorAll('[data-val]').forEach(function(i){i.addEventListener('input',function(){root.querySelectorAll('[data-team]').forEach(function(x){x.setAttribute('aria-pressed','false')});calc()})});calc()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot()})();